  'site.about.hero.eyebrow': 'CREWNBUILD ಬಗ್ಗೆ',
  'site.about.hero.title': 'ಇಪ್ಪತ್ತೈದು ವರ್ಷಗಳ ನಿರ್ಮಾಣ',
  'site.about.hero.highlight': 'ಕಾಂಕ್ರೀಟ್‌ನಲ್ಲಿ ನಂಬಿಕೆ.',
  'site.about.hero.sub': '2001ರಲ್ಲಿ ಐದು ಜನರ ಸೈಟ್ ತಂಡದಿಂದ ಭಾರತದ ಅತ್ಯಂತ ವಿಶ್ವಾಸಾರ್ಹ ನಿರ್ಮಾಣ ಸಂಸ್ಥೆಗಳಲ್ಲಿ ಒಂದಾಗಿ — ನಮ್ಮ ಕಥೆ ನಾವು ಹಿಂದೆ ಬಿಟ್ಟ ಕಟ್ಟಡಗಳಲ್ಲಿ ಬರೆದಿದೆ.',
  'site.about.story.eyebrow': 'ನಮ್ಮ ಕಥೆ',
  'site.about.story.title': 'ಒಂದು ಸೈಟ್ ತಂಡದಿಂದ',
  'site.about.story.highlight': 'ಪೂರ್ಣ ಪ್ರಮಾಣದ ನಿರ್ಮಾಣ ಸಂಸ್ಥೆಯವರೆಗೆ.',
  'site.about.story.p1': 'CREWNBUILD 2001ರಲ್ಲಿ ಹೈದರಾಬಾದ್‌ನಲ್ಲಿ ಒಂದೇ ಒಂದು ವಸತಿ ನಿರ್ಮಾಣ ಮತ್ತು ಸರಳ ವಾಗ್ದಾನದೊಂದಿಗೆ ಪ್ರಾರಂಭವಾಯಿತು — ಗ್ರಾಹಕರಿಗೆ ಪ್ರತಿ ರೂಪಾಯಿ, ಪ್ರತಿ ವಾರ ತೋರಿಸುವುದು. ಆ ವಾಗ್ದಾನವೇ ನಮ್ಮ ಆಪರೇಟಿಂಗ್ ಸಿಸ್ಟಂ ಆಯಿತು.',
  'site.about.story.p2': 'ಇಂದು ನಾವು 120+ ಇಂಜಿನಿಯರ್ಗಳು, ವಾಸ್ತುಶಿಲ್ಪಿಗಳು ಮತ್ತು ಯೋಜನಾ ವ್ಯವಸ್ಥಾಪಕರನ್ನು ನೇಮಿಸಿಕೊಂಡಿದ್ದೇವೆ, ಇವರು ವಸತಿ, ವಾಣಿಜ್ಯ ಮತ್ತು ಮೂಲಸೌಕರ್ಯದಲ್ಲಿ 850+ ಯೋಜನೆಗಳನ್ನು ತಲುಪಿಸಿದ್ದಾರೆ. ಗುಣಮಟ್ಟವನ್ನು ಹೊರಗುತ್ತಿಗೆ ಮಾಡಲಾಗದು ಎಂದು ನಾವು ನಂಬುವುದರಿಂದ ಇನ್-ಹೌಸ್ ವಿನ್ಯಾಸ ಮತ್ತು QA‌ನಲ್ಲಿ ಹೆಚ್ಚು ಹೂಡಿಕೆ ಮಾಡುತ್ತೇವೆ.',
  'site.about.story.est': 'ಸ್ಥಾ. 2001',
  'site.about.story.city': 'ಹೈದರಾಬಾದ್, ಭಾರತ',
  'site.about.h1': 'ಮೊದಲು ಸಮಗ್ರತೆ',
  'site.about.h1b': 'ಮುಕ್ತ ಲೆಡ್ಜರ್ಗಳು, ಪ್ರಾಮಾಣಿಕ ಅಂದಾಜುಗಳು ಮತ್ತು ಗುಪ್ತ ವೆಚ್ಚಗಳಿಲ್ಲ — ಎಂದಿಗೂ.',
  'site.about.h2': 'ನಿಖರ ವಿತರಣೆ',
  'site.about.h2b': 'ನಾವು ಲಿಖಿತವಾಗಿ ಬದ್ಧರಾಗಿ, ಈಡೇರಿಸುವ ಮೈಲಿಗಲ್ಲು ವೇಳಾಪಟ್ಟಿಗಳು.',
  'site.about.h3': 'ಒಬ್ಬ ಜವಾಬ್ದಾರಿಯುತ ಪಾಲುದಾರ',
  'site.about.h3b': 'ಬ್ಲೂಪ್ರಿಂಟ್‌ನಿಂದ ಹ್ಯಾಂಡ್‌ಓವರ್‌ವರೆಗೆ ಒಂದೇ ತಂಡ — ಬೆರಳು ತೋರಿಸುವುದಿಲ್ಲ.',
  'site.about.h4': 'ಬಾಳಿಕೆಗಾಗಿ ನಿರ್ಮಿಸಿ',
  'site.about.h4b': 'ಟ್ರೆಂಡ್‌ಗಳನ್ನು ಮೀರುವ ಸುಸ್ಥಿರ ವಸ್ತುಗಳು ಮತ್ತು ಇಂಜಿನಿಯರಿಂಗ್.',
  'site.about.values.eyebrow': 'ನಾವು ಯಾವುದಕ್ಕಾಗಿ ನಿಲ್ಲುತ್ತೇವೆ',
  'site.about.values.title': 'ಪ್ರತಿ ಸೈಟ್‌ನಲ್ಲೂ',
  'site.about.values.highlight': 'ಗೋಚರಿಸುವ ಮೌಲ್ಯಗಳು.',
  'site.about.hl1': 'ಪ್ರತಿ ಯೋಜನೆಯಲ್ಲಿ ರೆರಾ-ನೋಂದಾಯಿತ ಮತ್ತು ಸಂಪೂರ್ಣ ವಿಮೆ',
  'site.about.hl2': 'ಇನ್-ಹೌಸ್ ವಾಸ್ತುಶಿಲ್ಪಿಗಳು, ರಚನಾತ್ಮಕ & MEP ಇಂಜಿನಿಯರ್ಗಳು',
  'site.about.hl3': 'ಪ್ರತಿ ಸೈಟ್‌ನಲ್ಲಿ ಮೂರನೇ ವ್ಯಕ್ತಿಯ QA ಪ್ರಯೋಗಾಲಯಗಳು',
  'site.about.hl4': 'ಪ್ರತಿ ಗ್ರಾಹಕರಿಗೆ ಲೈವ್ ಯೋಜನಾ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್',
  'site.team.eyebrow': 'ನಾಯಕತ್ವ',
  'site.team.title': 'ತಮ್ಮ ಕೆಲಸದ ಹಿಂದೆ',
  'site.team.highlight': 'ನಿಲ್ಲುವ ಇಂಜಿನಿಯರ್ಗಳು.',
  'site.team.sub': 'ವಸತಿ, ವಾಣಿಜ್ಯ ಮತ್ತು ಮೂಲಸೌಕರ್ಯ ವಿತರಣೆಯಲ್ಲಿ ದಶಕಗಳ ಸಂಯುಕ್ತ ಅನುಭವ ಹೊಂದಿರುವ ನಾಯಕತ್ವ ತಂಡ.',
  'site.team.role1': 'ಸಂಸ್ಥಾಪಕ & ವ್ಯವಸ್ಥಾಪಕ ನಿರ್ದೇಶಕ',
  'site.team.role2': 'ಮುಖ್ಯ ವಾಸ್ತುಶಿಲ್ಪಿ',
  'site.team.role3': 'ಇಂಜಿನಿಯರಿಂಗ್ ಮುಖ್ಯಸ್ಥ',
  'site.team.role4': 'ಯೋಜನಾ ನಿರ್ದೇಶಕ',
  'site.team.bio1': 'ರಸ್ತೆಗಳು, ಬಂದರುಗಳು ಮತ್ತು ಎತ್ತರದ ವಸತಿ ಕಟ್ಟಡಗಳಲ್ಲಿ 26 ವರ್ಷಗಳ ಸಿವಿಲ್ ಇಂಜಿನಿಯರ್.',
  'site.team.bio2': 'ಸುಸ್ಥಿರ ವಸತಿಯಲ್ಲಿ ಪ್ರಶಸ್ತಿ ವಿಜೇತ ಕೆಲಸದೊಂದಿಗೆ ವಿನ್ಯಾಸ ಸ್ಟುಡಿಯೋವನ್ನು ಮುನ್ನಡೆಸುತ್ತಾರೆ.',
  'site.team.bio3': 'ಭೂಕಂಪ ವಲಯಗಳು ಮತ್ತು ಭಾರೀ ಮೂಲಸೌಕರ್ಯಕ್ಕಾಗಿ ರಚನಾತ್ಮಕ ತಜ್ಞ.',
  'site.team.bio4': 'ವಿತರಣಾ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ನಡೆಸುತ್ತಾರೆ — ಸಮಯಕ್ಕೆ ಸರಿಯಾಗಿ 850+ ಯೋಜನೆಗಳು.',
  'site.services.hero.eyebrow': 'ಸೇವೆಗಳು',
